const body = $input.first().json.body || $input.first().json;

const CODE_RE = /^[a-z][a-z0-9_]*\.(before|after)_[a-z0-9_]+$/;

const err = (message) => [{ json: { valid: false, statusCode: 400, body: { message } } }];

const id     = (body.id     || '').toString().trim();
const code   = (body.code   || '').toString().trim();
const name   = (body.name   || '').toString().trim();
const module = (body.module || 'core').toString().trim();
const timing = (body.timing || '').toString().trim();

if (!CODE_RE.test(code)) {
  return err('El código debe tener la forma <entidad>.<before|after>_<accion>, en minúsculas. Ejemplo: invoice.after_upsert');
}
if (!name || name.length > 120)      return err('El nombre es obligatorio y no puede superar los 120 caracteres.');
if (!module || module.length > 40)   return err('El módulo es obligatorio y no puede superar los 40 caracteres.');
if (timing !== 'before' && timing !== 'after') return err('El momento debe ser "before" o "after".');

// El timing tiene que ser coherente con el propio código: si no, el catálogo
// miente sobre cuándo corre el hook y quien escriba la customización se
// equivoca sin manera de darse cuenta.
const timingEnCodigo = code.includes('.before_') ? 'before' : 'after';
if (timingEnCodigo !== timing) {
  return err(`El código dice "${timingEnCodigo}" pero el momento seleccionado es "${timing}". Deben coincidir.`);
}

let payload_schema = body.payload_schema ?? {};
if (typeof payload_schema === 'string') {
  const s = payload_schema.trim();
  if (!s) payload_schema = {};
  else {
    try { payload_schema = JSON.parse(s); }
    catch (e) { return err('El esquema del payload no es JSON válido.'); }
  }
}
if (typeof payload_schema !== 'object' || Array.isArray(payload_schema) || payload_schema === null) {
  return err('El esquema del payload debe ser un objeto JSON.');
}

const payload_version = Number(body.payload_version ?? 1);
if (!Number.isInteger(payload_version) || payload_version < 1) {
  return err('La versión del payload debe ser un entero mayor o igual a 1.');
}

return [{ json: {
  valid: true,
  id: id || null,
  code, name, module, timing,
  description:     (body.description || '').toString().trim() || null,
  payload_schema:  JSON.stringify(payload_schema),
  payload_version,
  is_active:       body.is_active !== false,
} }];

const r = $input.first()?.json || {};

if (r.error) {
  const msg = (r.error?.message || String(r.error));
  // 23505 = unique_violation sobre hook_events.code
  if (msg.includes('hook_events_code_key') || msg.includes('duplicate key')) {
    return [{ json: { statusCode: 409, body: { message: 'Ya existe un evento con ese código.' } } }];
  }
  if (msg.includes('hook_events_code_format_check')) {
    return [{ json: { statusCode: 400, body: { message: 'El código no cumple el formato <entidad>.<before|after>_<accion>.' } } }];
  }
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar el evento: ' + msg } } }];
}

const MOTIVOS = {
  not_found:     [404, 'El evento que se intenta editar ya no existe.'],
  system_code:   [400, 'Este evento lo entrega el producto: su código no se puede cambiar porque está embebido en el flujo de n8n que lo dispara.'],
  system_timing: [400, 'Este evento lo entrega el producto: su momento (antes/después) no se puede cambiar.'],
};

if (r.violacion) {
  const [statusCode, message] = MOTIVOS[r.violacion] || [400, 'Operación no permitida.'];
  return [{ json: { statusCode, body: { message } } }];
}

if (!r.evento) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar el evento.' } } }];
}

return [{ json: { statusCode: 200, body: r.evento } }];
